// @ts-ignore Generated by the OpenNext build and absent before the first build.
import handler from './.open-next/worker.js'

const dailyCronRoutes: Record<number, string> = {
  3: '/api/cron/launch-campaign',
  4: '/api/cron/account-cleanup',
  5: '/api/cron/billing',
  6: '/api/cron/check-tokens',
  7: '/api/cron/sync-google-reviews',
}

type WorkerEnv = {
  APP_URL?: string
  CRON_SECRET?: string
  ENABLE_CRON_TRIGGERS?: string
  BOOKEASY_CLOUDFLARE_PREVIEW?: string
}

type CronEvent = { cron: string; scheduledTime: number }
type WorkerContext = { waitUntil(promise: Promise<unknown>): void }

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerContext) {
    const response = await handler.fetch(request, env, ctx)
    if (env.BOOKEASY_CLOUDFLARE_PREVIEW !== 'true') return response
    const headers = new Headers(response.headers)
    headers.set('X-Robots-Tag', 'noindex, nofollow')
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
  },
  async scheduled(event: CronEvent, env: WorkerEnv, ctx: WorkerContext) {
    if (env.BOOKEASY_CLOUDFLARE_PREVIEW === 'true' || env.ENABLE_CRON_TRIGGERS !== 'true') return
    const route = event.cron === '*/5 * * * *'
      ? '/api/cron/billing-payments'
      : event.cron === '0 3-7 * * *'
        ? dailyCronRoutes[new Date(event.scheduledTime).getUTCHours()]
        : undefined
    if (!route || !env.APP_URL || !env.CRON_SECRET) return

    // Dispatch internally: a same-zone fetch on a Worker route can reach the
    // legacy DNS origin instead of this Worker.
    ctx.waitUntil((async () => {
      const response = await handler.fetch(new Request(`${env.APP_URL}${route}`, {
        headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
      }), env, ctx)
      await response.arrayBuffer()
      if (!response.ok) throw new Error(`Cron ${route} failed: HTTP ${response.status}`)
    })())
  },
}
